import 'package:drift/drift.dart';

class Organizations extends Table { TextColumn get id=>text()(); TextColumn get nameAr=>text()(); TextColumn get nameEn=>text().nullable()(); @override Set<Column> get primaryKey=>{id}; }
class Departments extends Table { TextColumn get id=>text()(); TextColumn get code=>text().unique()(); TextColumn get nameAr=>text()(); TextColumn get nameEn=>text().nullable()(); TextColumn get parentDepartmentId=>text().nullable().references(Departments,#id)(); TextColumn get managerUserId=>text().nullable()(); BoolColumn get isActive=>boolean().withDefault(const Constant(true))(); IntColumn get sortOrder=>integer().withDefault(const Constant(0))(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get updatedAt=>dateTime()(); @override Set<Column> get primaryKey=>{id}; }
class Roles extends Table { TextColumn get id=>text()(); TextColumn get code=>text().unique()(); TextColumn get nameAr=>text()(); TextColumn get nameEn=>text().nullable()(); @override Set<Column> get primaryKey=>{id}; }
class Permissions extends Table { TextColumn get id=>text()(); TextColumn get code=>text().unique()(); @override Set<Column> get primaryKey=>{id}; }
class RolePermissions extends Table { TextColumn get id=>text()(); TextColumn get roleId=>text().references(Roles,#id)(); TextColumn get permissionId=>text().references(Permissions,#id)(); @override Set<Column> get primaryKey=>{id}; @override List<Set<Column>> get uniqueKeys=>[{roleId,permissionId}]; }
class Users extends Table { TextColumn get id=>text()(); TextColumn get employeeNumber=>text().unique()(); TextColumn get nameAr=>text()(); TextColumn get nameEn=>text().nullable()(); TextColumn get email=>text().nullable()(); TextColumn get phone=>text().nullable()(); TextColumn get jobTitleAr=>text()(); TextColumn get jobTitleEn=>text().nullable()(); TextColumn get departmentId=>text().references(Departments,#id)(); TextColumn get managerId=>text().nullable().references(Users,#id)(); TextColumn get roleId=>text().references(Roles,#id)(); TextColumn get avatarInitials=>text()(); TextColumn get status=>text()(); BoolColumn get isActive=>boolean().withDefault(const Constant(true))(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get updatedAt=>dateTime()(); @override Set<Column> get primaryKey=>{id}; }
class Teams extends Table { TextColumn get id=>text()(); TextColumn get code=>text().unique()(); TextColumn get departmentId=>text().references(Departments,#id)(); TextColumn get nameAr=>text()(); TextColumn get nameEn=>text().nullable()(); TextColumn get managerUserId=>text().nullable().references(Users,#id)(); BoolColumn get isQueueEnabled=>boolean().withDefault(const Constant(false))(); BoolColumn get isActive=>boolean().withDefault(const Constant(true))(); IntColumn get sortOrder=>integer()(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get updatedAt=>dateTime()(); @override Set<Column> get primaryKey=>{id}; }
class TeamMemberships extends Table { TextColumn get id=>text()(); TextColumn get teamId=>text().references(Teams,#id)(); TextColumn get userId=>text().references(Users,#id)(); TextColumn get membershipRole=>text()(); BoolColumn get isActive=>boolean().withDefault(const Constant(true))(); DateTimeColumn get joinedAt=>dateTime()(); DateTimeColumn get leftAt=>dateTime().nullable()(); @override Set<Column> get primaryKey=>{id}; @override List<Set<Column>> get uniqueKeys=>[{teamId,userId}]; }
class Priorities extends Table { TextColumn get id=>text()(); TextColumn get code=>text().unique()(); TextColumn get labelAr=>text()(); TextColumn get labelEn=>text()(); IntColumn get level=>integer()(); TextColumn get iconKey=>text()(); TextColumn get semanticColorKey=>text()(); IntColumn get defaultReminderMinutes=>integer()(); IntColumn get defaultEscalationMinutes=>integer()(); IntColumn get sortOrder=>integer()(); BoolColumn get isActive=>boolean()(); @override Set<Column> get primaryKey=>{id}; }
class Categories extends Table { TextColumn get id=>text()(); TextColumn get code=>text().unique()(); TextColumn get labelAr=>text()(); TextColumn get labelEn=>text()(); BoolColumn get defaultApprovalRequired=>boolean()(); BoolColumn get defaultEvidenceRequired=>boolean()(); TextColumn get defaultPriorityId=>text().references(Priorities,#id)(); BoolColumn get allowDecline=>boolean()(); BoolColumn get allowExtension=>boolean()(); IntColumn get defaultEstimatedEffortMinutes=>integer()(); BoolColumn get isActive=>boolean()(); IntColumn get sortOrder=>integer()(); @override Set<Column> get primaryKey=>{id}; }
class ConfidentialityLevels extends Table { TextColumn get id=>text()(); TextColumn get code=>text().unique()(); TextColumn get labelAr=>text()(); TextColumn get labelEn=>text()(); IntColumn get level=>integer()(); TextColumn get semanticColorKey=>text()(); BoolColumn get isActive=>boolean()(); IntColumn get sortOrder=>integer()(); @override Set<Column> get primaryKey=>{id}; }
class RecurrenceRules extends Table { TextColumn get id=>text()(); TextColumn get frequency=>text()(); IntColumn get interval=>integer().check(interval.isBiggerThanValue(0))(); TextColumn get weekdaysJson=>text().nullable()(); IntColumn get dayOfMonth=>integer().nullable()(); BoolColumn get useLastWorkingDay=>boolean()(); DateTimeColumn get startDate=>dateTime()(); TextColumn get endType=>text()(); DateTimeColumn get endDate=>dateTime().nullable()(); IntColumn get occurrenceCount=>integer().nullable()(); BoolColumn get isPaused=>boolean()(); TextColumn get createdBy=>text().references(Users,#id)(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get updatedAt=>dateTime()(); @override Set<Column> get primaryKey=>{id}; }
class Tasks extends Table { TextColumn get id=>text()(); TextColumn get taskNumber=>text().unique()(); TextColumn get titleAr=>text().check(titleAr.length.isBiggerThanValue(0))(); TextColumn get titleEn=>text().nullable()(); TextColumn get descriptionAr=>text()(); TextColumn get descriptionEn=>text().nullable()(); TextColumn get creatorId=>text().references(Users,#id)(); TextColumn get creatorRoleCode=>text()(); TextColumn get creationSource=>text()(); TextColumn get assignmentMode=>text()(); TextColumn get leadOwnerId=>text().nullable().references(Users,#id)(); TextColumn get assignedTeamId=>text().nullable().references(Teams,#id)(); TextColumn get parentTaskId=>text().nullable().references(Tasks,#id)(); TextColumn get batchId=>text().nullable()(); TextColumn get priorityId=>text().references(Priorities,#id)(); TextColumn get categoryId=>text().references(Categories,#id)(); TextColumn get status=>text()(); TextColumn get confidentialityLevelId=>text().references(ConfidentialityLevels,#id)(); TextColumn get visibilityType=>text()(); DateTimeColumn get plannedStartDate=>dateTime().nullable()(); DateTimeColumn get dueDate=>dateTime()(); TextColumn get dueTime=>text().nullable()(); IntColumn get estimatedEffortMinutes=>integer().nullable()(); IntColumn get progressPercentage=>integer().check(progressPercentage.isBetweenValues(0,100))(); BoolColumn get approvalRequired=>boolean()(); BoolColumn get completionEvidenceRequired=>boolean()(); BoolColumn get allowDecline=>boolean()(); BoolColumn get allowExtension=>boolean()(); TextColumn get approverId=>text().nullable().references(Users,#id)(); TextColumn get approvalStatus=>text()(); BoolColumn get isPersonal=>boolean()(); BoolColumn get isRecurring=>boolean()(); TextColumn get recurrenceRuleId=>text().nullable().references(RecurrenceRules,#id)(); TextColumn get recurrenceSourceTaskId=>text().nullable().references(Tasks,#id)(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get updatedAt=>dateTime()(); DateTimeColumn get acknowledgedAt=>dateTime().nullable()(); DateTimeColumn get startedAt=>dateTime().nullable()(); DateTimeColumn get completedAt=>dateTime().nullable()(); DateTimeColumn get cancelledAt=>dateTime().nullable()(); DateTimeColumn get lastSyncedAt=>dateTime().nullable()(); IntColumn get localVersion=>integer().withDefault(const Constant(1))(); IntColumn get serverVersion=>integer().nullable()(); TextColumn get syncState=>text()(); BoolColumn get isLocallyModified=>boolean()(); BoolColumn get isDeleted=>boolean().withDefault(const Constant(false))(); @override Set<Column> get primaryKey=>{id}; }
class TaskAssignments extends Table { TextColumn get id=>text()(); TextColumn get taskId=>text().references(Tasks,#id)(); TextColumn get userId=>text().references(Users,#id)(); TextColumn get assignmentRole=>text()(); TextColumn get assignmentStatus=>text()(); BoolColumn get isPrimary=>boolean()(); DateTimeColumn get assignedAt=>dateTime()(); DateTimeColumn get acknowledgedAt=>dateTime().nullable()(); DateTimeColumn get completedAt=>dateTime().nullable()(); IntColumn get contributionPercentage=>integer().nullable().check(contributionPercentage.isBetweenValues(0,100))(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get updatedAt=>dateTime()(); @override Set<Column> get primaryKey=>{id}; }
class ChecklistItems extends Table { TextColumn get id=>text()(); TextColumn get taskId=>text().references(Tasks,#id)(); TextColumn get titleAr=>text()(); TextColumn get titleEn=>text().nullable()(); BoolColumn get isMandatory=>boolean()(); BoolColumn get isCompleted=>boolean()(); TextColumn get completedBy=>text().nullable().references(Users,#id)(); DateTimeColumn get completedAt=>dateTime().nullable()(); IntColumn get sortOrder=>integer()(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get updatedAt=>dateTime()(); @override Set<Column> get primaryKey=>{id}; }
class TaskComments extends Table { TextColumn get id=>text()(); TextColumn get taskId=>text().references(Tasks,#id)(); TextColumn get authorId=>text().references(Users,#id)(); TextColumn get body=>text()(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get updatedAt=>dateTime()(); BoolColumn get isEdited=>boolean()(); TextColumn get replyToCommentId=>text().nullable().references(TaskComments,#id)(); TextColumn get mentionUserIdsJson=>text()(); BoolColumn get isDeleted=>boolean()(); TextColumn get syncState=>text()(); @override Set<Column> get primaryKey=>{id}; }
class TaskAttachments extends Table { TextColumn get id=>text()(); TextColumn get taskId=>text().references(Tasks,#id)(); TextColumn get commentId=>text().nullable().references(TaskComments,#id)(); TextColumn get fileName=>text()(); TextColumn get fileType=>text()(); TextColumn get localPath=>text().nullable()(); TextColumn get mockRemotePath=>text().nullable()(); IntColumn get sizeBytes=>integer().check(sizeBytes.isBiggerOrEqualValue(0))(); TextColumn get attachmentCategory=>text()(); TextColumn get uploadedBy=>text().references(Users,#id)(); DateTimeColumn get createdAt=>dateTime()(); TextColumn get syncState=>text()(); @override Set<Column> get primaryKey=>{id}; }
class TaskBlockers extends Table { TextColumn get id=>text()(); TextColumn get taskId=>text().references(Tasks,#id)(); TextColumn get reportedBy=>text().references(Users,#id)(); TextColumn get blockerType=>text()(); TextColumn get description=>text()(); TextColumn get responsibleParty=>text()(); DateTimeColumn get startedAt=>dateTime()(); DateTimeColumn get resolvedAt=>dateTime().nullable()(); TextColumn get resolutionNote=>text().nullable()(); TextColumn get status=>text()(); @override Set<Column> get primaryKey=>{id}; }
class DeadlineExtensionRequests extends Table { TextColumn get id=>text()(); TextColumn get taskId=>text().references(Tasks,#id)(); TextColumn get requestedBy=>text().references(Users,#id)(); DateTimeColumn get currentDueDate=>dateTime()(); DateTimeColumn get requestedDueDate=>dateTime()(); TextColumn get reason=>text()(); TextColumn get status=>text()(); TextColumn get reviewedBy=>text().nullable().references(Users,#id)(); DateTimeColumn get reviewedAt=>dateTime().nullable()(); TextColumn get reviewNote=>text().nullable()(); @override Set<Column> get primaryKey=>{id}; }
class TaskApprovals extends Table { TextColumn get id=>text()(); TextColumn get taskId=>text().references(Tasks,#id)(); TextColumn get approverId=>text().references(Users,#id)(); TextColumn get status=>text()(); DateTimeColumn get submittedAt=>dateTime()(); DateTimeColumn get reviewedAt=>dateTime().nullable()(); TextColumn get reviewComment=>text().nullable()(); IntColumn get sequenceNumber=>integer()(); @override Set<Column> get primaryKey=>{id}; }
class AppNotifications extends Table { TextColumn get id=>text()(); TextColumn get recipientId=>text().references(Users,#id)(); TextColumn get type=>text()(); TextColumn get titleAr=>text()(); TextColumn get titleEn=>text().nullable()(); TextColumn get messageAr=>text()(); TextColumn get messageEn=>text().nullable()(); TextColumn get taskId=>text().nullable().references(Tasks,#id)(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get readAt=>dateTime().nullable()(); BoolColumn get isRead=>boolean()(); TextColumn get deliveryChannel=>text()(); TextColumn get deliveryStatus=>text()(); @override Set<Column> get primaryKey=>{id}; }
