class SyncOperations extends Table { TextColumn get id=>text()(); TextColumn get entityType=>text()(); TextColumn get entityId=>text()(); TextColumn get operationType=>text()(); TextColumn get payloadJson=>text()(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get lastAttemptAt=>dateTime().nullable()(); IntColumn get retryCount=>integer()(); TextColumn get status=>text()(); TextColumn get errorMessage=>text().nullable()(); TextColumn get conflictType=>text()(); @override Set<Column> get primaryKey=>{id}; }
class SavedTaskFilters extends Table { TextColumn get id=>text()(); TextColumn get userId=>text().references(Users,#id)(); TextColumn get name=>text()(); TextColumn get filterJson=>text()(); BoolColumn get isDefault=>boolean()(); DateTimeColumn get createdAt=>dateTime()(); DateTimeColumn get updatedAt=>dateTime()(); @override Set<Column> get primaryKey=>{id}; }
