class TaskTemplates extends Table { TextColumn get id=>text()(); TextColumn get titleAr=>text()(); TextColumn get titleEn=>text().nullable()(); TextColumn get descriptionAr=>text()(); TextColumn get descriptionEn=>text().nullable()(); TextColumn get categoryId=>text().references(Categories,#id)(); TextColumn get priorityId=>text().references(Priorities,#id)(); IntColumn get defaultEffortMinutes=>integer()(); BoolColumn get approvalRequired=>boolean()(); BoolColumn get evidenceRequired=>boolean()(); TextColumn get recurrenceRuleId=>text().nullable().references(RecurrenceRules,#id)(); BoolColumn get isActive=>boolean()(); @override Set<Column> get primaryKey=>{id}; }
